#include <IpStdCInterface.h>

static bool objective(ipindex n, ipnumber *x, bool fresh, ipnumber *f, void *data) {
  *f = x[0] * x[0] + x[1] * x[1];
  return true;
}

static bool gradient(ipindex n, ipnumber *x, bool fresh, ipnumber *grad, void *data) {
  grad[0] = 2 * x[0];
  grad[1] = 2 * x[1];
  return true;
}

static bool constraints(ipindex n, ipnumber *x, bool fresh, ipindex m, ipnumber *g, void *data) {
  g[0] = x[0] + x[1];
  return true;
}

static bool jacobian(ipindex n, ipnumber *x, bool fresh, ipindex m, ipindex count,
                     ipindex *rows, ipindex *cols, ipnumber *values, void *data) {
  if (values) values[0] = values[1] = 1;
  else {
    rows[0] = rows[1] = 0;
    cols[0] = 0;
    cols[1] = 1;
  }
  return true;
}

static bool hessian(ipindex n, ipnumber *x, bool fresh, ipnumber factor, ipindex m,
                    ipnumber *lambda, bool fresh_lambda, ipindex count,
                    ipindex *rows, ipindex *cols, ipnumber *values, void *data) {
  if (values) values[0] = values[1] = 2 * factor;
  else {
    rows[0] = cols[0] = 0;
    rows[1] = cols[1] = 1;
  }
  return true;
}

static bool intermediate(ipindex mode, ipindex iter, ipnumber f, ipnumber inf_pr,
                         ipnumber inf_du, ipnumber mu, ipnumber norm, ipnumber regularization,
                         ipnumber alpha_du, ipnumber alpha_pr, ipindex trials, void *data) {
  ((double *)data)[3] = iter;
  return true;
}

__declspec(dllexport) int probe(double *out) {
  ipnumber lower[] = {-100, -100}, upper[] = {100, 100}, target[] = {10};
  ipnumber x[] = {0, 0};
  IpoptProblem p = CreateIpoptProblem(2, lower, upper, 1, target, target, 2, 2, 0,
                                     objective, constraints, gradient, jacobian, hessian);
  if (!p) return -999;
  if (!AddIpoptStrOption(p, "linear_solver", "mumps") ||
      !AddIpoptStrOption(p, "sb", "yes") ||
      !AddIpoptIntOption(p, "print_level", 0) ||
      !AddIpoptNumOption(p, "tol", 1e-10) ||
      !SetIntermediateCallback(p, intermediate)) {
    FreeIpoptProblem(p);
    return -998;
  }
  int status = IpoptSolve(p, x, 0, &out[2], 0, 0, 0, out);
  out[0] = x[0];
  out[1] = x[1];
  FreeIpoptProblem(p);
  return status;
}
